#pragma warning disable CA1725
using FluentValidation;
using MediatR;
using WhatsBiz.Application.Common.Interfaces;
namespace WhatsBiz.Application.Features.Receivables;
public sealed record PaymentSplitInput(string PaymentMode, decimal Amount, string? ReferenceNumber, string? ChequeNumber, DateOnly? ChequeDate, string? BankName); public sealed record ReceiptAllocationInput(Guid InvoiceId, decimal Amount); public sealed record PaymentAllocationInput(Guid PurchaseInvoiceId, decimal Amount); public sealed record ReceiptInput(Guid CustomerId, string ReceiptType, DateTimeOffset ReceiptDate, string? ReferenceNumber, string? Remarks, IReadOnlyCollection<PaymentSplitInput> Items, IReadOnlyCollection<ReceiptAllocationInput> Allocations); public sealed record PaymentInput(Guid SupplierId, string PaymentType, DateTimeOffset PaymentDate, string? ReferenceNumber, string? Remarks, IReadOnlyCollection<PaymentSplitInput> Items, IReadOnlyCollection<PaymentAllocationInput> Allocations); public sealed record DocumentResultDto(Guid DocumentId, string DocumentNumber, decimal TotalAmount, decimal AllocatedAmount); public sealed record FinancialDocumentDto(Guid Id, string Number, DateTimeOffset EntryDate, string PartyCode, string PartyName, string EntryType, decimal TotalAmount, decimal AllocatedAmount, decimal OnAccountAmount, string Status, string? ReferenceNumber, string? Remarks); public sealed record PagedFinancialDocuments(IReadOnlyCollection<FinancialDocumentDto> Items, int TotalCount, int PageNumber, int PageSize); public sealed record OutstandingDto(Guid Id, Guid PartyId, string PartyCode, string PartyName, Guid InvoiceId, string InvoiceNumber, DateTimeOffset InvoiceDate, DateTimeOffset DueDate, decimal InvoiceAmount, decimal PaidAmount, decimal OutstandingAmount, int AgeDays, string AgeBucket); public sealed record FollowUpInput(Guid CustomerId, Guid? InvoiceId, DateTimeOffset FollowUpDate, DateTimeOffset? NextFollowUpDate, DateTimeOffset? PaymentCommitmentDate, string CommunicationMode, string? Notes, string? Outcome); public sealed record FollowUpDto(Guid Id, Guid CustomerId, string CustomerCode, string CustomerName, Guid? InvoiceId, string? InvoiceNumber, DateTimeOffset FollowUpDate, DateTimeOffset? NextFollowUpDate, DateTimeOffset? PaymentCommitmentDate, string CommunicationMode, string? Notes, string? Outcome, string? CreatedBy);
public sealed record GetReceipts(string? Search, Guid? CustomerId, DateTimeOffset? From, DateTimeOffset? To, int PageNumber, int PageSize) : IRequest<PagedFinancialDocuments>; public sealed record PostReceipt(ReceiptInput Input) : IRequest<DocumentResultDto>; public sealed record GetPayments(string? Search, Guid? SupplierId, DateTimeOffset? From, DateTimeOffset? To, int PageNumber, int PageSize) : IRequest<PagedFinancialDocuments>; public sealed record PostPayment(PaymentInput Input) : IRequest<DocumentResultDto>; public sealed record GetOutstanding(string PartyType, Guid? PartyId, string? Search, string? AgeBucket) : IRequest<IReadOnlyCollection<OutstandingDto>>; public sealed record GetFollowUps(Guid? CustomerId) : IRequest<IReadOnlyCollection<FollowUpDto>>; public sealed record SaveFollowUp(FollowUpInput Input) : IRequest<Guid>;
public sealed class ReceiptInputValidator : AbstractValidator<PostReceipt> { public ReceiptInputValidator() { RuleFor(x => x.Input.CustomerId).NotEmpty(); RuleFor(x => x.Input.ReceiptType).Must(x => x is "CUSTOMER" or "ADVANCE" or "INVOICE_WISE" or "ON_ACCOUNT"); RuleFor(x => x.Input.Items).NotEmpty(); RuleForEach(x => x.Input.Items).ChildRules(i => { i.RuleFor(x => x.PaymentMode).NotEmpty(); i.RuleFor(x => x.Amount).GreaterThan(0); }); RuleFor(x => x.Input).Must(x => x.Allocations.Sum(a => a.Amount) <= x.Items.Sum(i => i.Amount)).WithMessage("Allocations cannot exceed receipt total."); } }
public sealed class PaymentInputValidator : AbstractValidator<PostPayment> { public PaymentInputValidator() { RuleFor(x => x.Input.SupplierId).NotEmpty(); RuleFor(x => x.Input.PaymentType).Must(x => x is "SUPPLIER" or "ADVANCE" or "INVOICE_WISE" or "ON_ACCOUNT"); RuleFor(x => x.Input.Items).NotEmpty(); RuleForEach(x => x.Input.Items).ChildRules(i => { i.RuleFor(x => x.PaymentMode).NotEmpty(); i.RuleFor(x => x.Amount).GreaterThan(0); }); RuleFor(x => x.Input).Must(x => x.Allocations.Sum(a => a.Amount) <= x.Items.Sum(i => i.Amount)).WithMessage("Allocations cannot exceed payment total."); } }
public sealed class FollowUpValidator : AbstractValidator<SaveFollowUp> { public FollowUpValidator() { RuleFor(x => x.Input.CustomerId).NotEmpty(); RuleFor(x => x.Input.FollowUpDate).NotEmpty(); RuleFor(x => x.Input.CommunicationMode).NotEmpty().MaximumLength(30); RuleFor(x => x.Input.Notes).MaximumLength(2000); } }
public sealed class ReceivablesHandlers(IReceivablesRepository repository, ICurrentUserService user) : IRequestHandler<GetReceipts, PagedFinancialDocuments>, IRequestHandler<PostReceipt, DocumentResultDto>, IRequestHandler<GetPayments, PagedFinancialDocuments>, IRequestHandler<PostPayment, DocumentResultDto>, IRequestHandler<GetOutstanding, IReadOnlyCollection<OutstandingDto>>, IRequestHandler<GetFollowUps, IReadOnlyCollection<FollowUpDto>>, IRequestHandler<SaveFollowUp, Guid> { public Task<PagedFinancialDocuments> Handle(GetReceipts q, CancellationToken t) => repository.History("RECEIPT", q.Search, q.CustomerId, q.From, q.To, q.PageNumber, q.PageSize, t); public Task<DocumentResultDto> Handle(PostReceipt q, CancellationToken t) => repository.PostReceipt(q.Input, user.Username, t); public Task<PagedFinancialDocuments> Handle(GetPayments q, CancellationToken t) => repository.History("PAYMENT", q.Search, q.SupplierId, q.From, q.To, q.PageNumber, q.PageSize, t); public Task<DocumentResultDto> Handle(PostPayment q, CancellationToken t) => repository.PostPayment(q.Input, user.Username, t); public Task<IReadOnlyCollection<OutstandingDto>> Handle(GetOutstanding q, CancellationToken t) => repository.Outstanding(q.PartyType, q.PartyId, q.Search, q.AgeBucket, t); public Task<IReadOnlyCollection<FollowUpDto>> Handle(GetFollowUps q, CancellationToken t) => repository.FollowUps(q.CustomerId, t); public Task<Guid> Handle(SaveFollowUp q, CancellationToken t) => repository.SaveFollowUp(q.Input, user.Username, t); }
